<?php $pageTitle='Finance Reports';require_once __DIR__.'/../includes/header.php';require_once __DIR__.'/../includes/sidebar.php';requireRole(['owner','manager']);$db=getDB();$club=$_SESSION['club_id'];$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$sum=$db->prepare("SELECT COALESCE(SUM(total_amount),0) total,COALESCE(SUM(table_amount),0) tables,COALESCE(SUM(cafe_amount),0) cafe,COUNT(*) sessions FROM sessions WHERE club_id=? AND status='completed' AND DATE(end_time) BETWEEN ? AND ?");$sum->execute([$club,$from,$to]);$sum=$sum->fetch();$ex=$db->prepare('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE club_id=? AND expense_date BETWEEN ? AND ?');$ex->execute([$club,$from,$to]);$expenses=(float)$ex->fetchColumn();$daily=$db->prepare("SELECT DATE(end_time) d,SUM(total_amount) revenue FROM sessions WHERE club_id=? AND status='completed' AND DATE(end_time) BETWEEN ? AND ? GROUP BY DATE(end_time) ORDER BY d");$daily->execute([$club,$from,$to]);$daily=$daily->fetchAll();$tables=$db->prepare("SELECT t.table_number,SUM(s.total_amount) revenue,COUNT(s.id) sessions FROM tables t LEFT JOIN sessions s ON s.table_id=t.id AND s.status='completed' AND DATE(s.end_time) BETWEEN ? AND ? WHERE t.club_id=? GROUP BY t.id ORDER BY revenue DESC");$tables->execute([$from,$to,$club]);$tables=$tables->fetchAll();?><h1 class="text-2xl font-bold">Finance Reports</h1><form class="card mt-5 flex flex-wrap gap-3 items-end"><div><label class="label">From</label><input class="input" type="date" name="from" value="<?=$from?>"></div><div><label class="label">To</label><input class="input" type="date" name="to" value="<?=$to?>"></div><button class="btn-primary">Apply Period</button></form><div class="grid grid-cols-2 xl:grid-cols-4 gap-4 mt-5"><?php foreach([['Total Revenue',$sum['total'],'text-green-400'],['Table Revenue',$sum['tables'],''],['Café Revenue',$sum['cafe'],'text-blue-400'],['Total Expenses',$expenses,'text-orange-400'],['Net Profit',$sum['total']-$expenses,'text-emerald-400'],['Sessions',$sum['sessions'],'']] as [$l,$v,$c]):?><div class="card"><p class="text-xs uppercase text-slate-400"><?=$l?></p><p class="text-xl font-bold mt-2 <?=$c?>"><?=is_numeric($v)&&$l==='Sessions'?$v:money($v)?></p></div><?php endforeach?></div><div class="grid xl:grid-cols-2 gap-5 mt-5"><section class="card"><h2 class="font-bold mb-3">Daily Revenue</h2><canvas id="revenue"></canvas></section><section class="card"><h2 class="font-bold mb-3">Revenue by Table</h2><canvas id="tableRevenue"></canvas></section></div><script>const opts={plugins:{legend:{labels:{color:'#cbd5e1'}},},scales:{x:{ticks:{color:'#94a3b8'},grid:{color:'#334155'}},y:{ticks:{color:'#94a3b8'},grid:{color:'#334155'}}}};new Chart(document.getElementById('revenue'),{type:'line',data:{labels:<?=json_encode(array_column($daily,'d'))?>,datasets:[{label:'Revenue',data:<?=json_encode(array_column($daily,'revenue'))?>,borderColor:'#22c55e',backgroundColor:'#22c55e33',fill:true}]},options:opts});new Chart(document.getElementById('tableRevenue'),{type:'bar',data:{labels:<?=json_encode(array_column($tables,'table_number'))?>,datasets:[{label:'Revenue',data:<?=json_encode(array_column($tables,'revenue'))?>,backgroundColor:'#3b82f6'}]},options:opts});</script><?php require __DIR__.'/../includes/footer.php'; ?>
